Here's a Python program that meets your requirements. This program includes functions for calculating the area and perimeter of a rectangle, the volume and surface area of a sphere, and the sum of the squares of two numbers. The main part of the program prompts the user to choose an operation and then calls the corresponding function with user-provided inputs.

```python
import math

def get_user_input(prompt):
    """Get user input and validate it."""
    while True:
        try:
            user_input = input(prompt)
            return int(user_input)
        except ValueError:
            print("Invalid input. Please enter a number.")

def rectangle_area_perimeter(length, width):
    """Calculate the area and perimeter of a rectangle."""
    area = length * width
    perimeter = 2 * (length + width)
    return area, perimeter

def sphere_volume_surface_area(radius):
    """Calculate the volume and surface area of a sphere."""
    volume = (4/3) * math.pi * (radius ** 3)
    surface_area = 4 * math.pi * (radius ** 2)
    return volume, surface_area

def sum_of_squares(num1, num2):
    """Calculate the sum of the squares of two numbers."""
    return (num1 ** 2 + num2 ** 2)

def main():
    """Prompt the user to choose an operation and call the corresponding function."""
    operations = {
        1: rectangle_area_perimeter,
        2: sphere_volume_surface_area,
        3: sum_of_squares
    }

    while True:
        operation_number = get_user_input("Choose an operation: ")
        if operation_number in operations:
            break

    length, width = map(float, input("Enter the length and width (separated by a space): ").split())
    radius = float(input("Enter the radius: "))
    num1, num2 = map(float, input("Enter two numbers (separated by a space): ").split())

    operation = operations[operation_number]
    result = operation(length, width, radius, num1, num2)

    print(f"The result of the chosen operation with the given parameters is:")
    for key, value in result.items():
        print(f"{key}: {value}")

if __name__ == "__main__":
    main()
```

This program will prompt the user to choose an operation, enter the necessary parameters, and then display the calculated result.
